  "arguments": [
    {
      "claim": "The sustained campaign of sniping and shelling was a prohibited act of terror against the civilian population under Article 51(2) of Additional Protocol I.",
      "reasoning": "Article 51(2) expressly forbids \"Acts or threats of violence the primary purpose of which is to spread terror among the civilian population\" and also bars making the civilian population the object of attack. The factual record shows a systematic, months‑long pattern of attacks aimed at civilians in daily activities, with no identifiable military objective and no discernible military advantage, indicating that the primary purpose was to intimidate and terrorise the population. Such intent can be inferred from the nature, scale and timing of the attacks, satisfying the statutory requirement.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "51(2)",
          "quoted_text": "The civilian population as such, as well as individual civilians, shall not be the object of attack. Acts or threats of violence the primary purpose of which is to spread terror among the civilian population are prohibited."
        }
      ]
    },
    {
      "claim": "The campaign constitutes a war crime of intentionally directing attacks against the civilian population under Article 8(2)(b)(i) of the Rome Statute.",
      "reasoning": "Article 8(2)(b)(i) criminalises \"Intentionally directing attacks against the civilian population as such or against individual civilians not taking direct part in hostilities\". The accused ordered, facilitated and encouraged the sniping and shelling, exercised effective command, and received regular reports, demonstrating the requisite intent to direct attacks at civilians. The attacks were deliberately aimed at civilians, not at any military objective, fulfilling the element of intentional direction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(i)",
          "quoted_text": "Intentionally directing attacks against the civilian population as such or against individual civilians not taking direct part in hostilities;"
        }
      ]
    },
    {
      "claim": "The campaign violated the distinction, precaution and proportionality obligations of Article 57 and the prohibition of indiscriminate attacks in Article 51(4) of Additional Protocol I, constituting a grave breach.",
      "reasoning": "Article 57 requires constant care to spare civilians and states that no provision may be interpreted as authorising attacks against the civilian population. Article 51(4) prohibits indiscriminate attacks, defined as those not directed at a specific military objective. The repeated shelling of civilian queues, funerals and intersections, without any verified military target and with knowledge that excessive civilian casualties would result, demonstrates a failure to verify targets, to take feasible precautions, and to refrain from attacks that would cause excessive civilian harm. This breaches both the precautionary duty of Article 57 and the indiscriminate‑attack prohibition of Article 51(4).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "57",
          "quoted_text": "No provision of this Article may be construed as authorizing any attacks against the civilian population, civilians or civilian objects."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "51",
          "quoted_text": "Indiscriminate attacks are prohibited. Indiscriminate attacks are: (a) those which are not directed at a specific military objective;"
        }
      ]
    }
  ]
}

